<script lang="ts">import AcademicEmptyState from '$lib/components/academic/AcademicEmptyState.svelte'; import AcademicErrorState from '$lib/components/academic/AcademicErrorState.svelte'; import SourceBadge from '$lib/components/academic/SourceBadge.svelte'; import PageHeader from '$lib/components/shell/PageHeader.svelte'; let { data } = $props(); function groupByCategory(items: typeof data.resources) { const groups = new Map<string, typeof data.resources>(); for (const item of items) { const key=item.category||'Other'; const values=groups.get(key)??[]; values.push(item); groups.set(key,values); } return [...groups.entries()]; }</script>
<svelte:head><title>Academic Resources · IMS Academic Hub</title></svelte:head>
<div class="mx-auto grid w-full max-w-[1180px] gap-7 px-4 py-7 sm:px-6 sm:py-9"><PageHeader eyebrow="Official resources" title="Forms, templates & academic links." description="The hub points to authoritative resources instead of maintaining unofficial copies that can go stale." />
{#if !data.repositoryStatus.configured}<AcademicEmptyState title="Resources are not connected yet" message="No public academic repository is configured in this deployment." />{:else if !data.repositoryStatus.available}<AcademicErrorState message={data.repositoryStatus.message} />{:else if data.resources.length === 0}<AcademicEmptyState title="No published resources yet" message="Only verified official links are shown here." />{:else}<div class="grid gap-7">{#each groupByCategory(data.resources) as [category, items]}<section class="grid gap-3" aria-labelledby={`resource-${category}`}><header class="flex items-end justify-between border-b border-line pb-3"><div><p class="font-mono text-xs font-semibold uppercase tracking-[.12em] text-ims-blue-ink">Category</p><h2 class="text-2xl font-semibold" id={`resource-${category}`}>{category}</h2></div><span class="font-mono text-sm text-muted">{items.length}</span></header><div class="divide-y divide-line border-y border-line bg-white">{#each items as resource}<article class="grid gap-3 border-l-4 border-ims-blue-deep p-4 md:grid-cols-[1fr_auto] md:items-center" id={`resource-${resource.slug}`}><div><h3 class="text-lg font-bold text-ink-strong">{resource.title}</h3>{#if resource.description}<p class="mt-1 leading-relaxed text-muted">{resource.description}</p>{/if}<div class="mt-3"><SourceBadge label={resource.meta.sourceLabel} url={resource.meta.sourceUrl} lastVerifiedAt={resource.lastCheckedAt} freshnessLabel="Checked" /></div></div><a class="inline-flex min-h-11 items-center border border-line-strong px-3 font-bold no-underline hover:bg-sky-50" href={resource.officialUrl} target="_blank" rel="noreferrer">Open Official Resource ↗</a></article>{/each}</div></section>{/each}</div>{/if}</div>
